param([int]$Port=3100,[string]$OutputRoot='')
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;if(-not$OutputRoot){$OutputRoot=Join-Path $root 'evidence/governance/copilot-v1.2/p9/controlled-reproduction/fault-isolation'};New-Item -ItemType Directory -Path $OutputRoot -Force|Out-Null
$env:PORT="$Port";$env:AGM_DIAGNOSTIC_TELEMETRY_PATH=Join-Path $OutputRoot 'server-telemetry.jsonl';$env:AGM_DIAGNOSTIC_FAULTS='AUTHORIZED';$preload=Join-Path $root 'scripts/basic-diagnostic-preload.cjs';$env:NODE_OPTIONS="--require=$preload --expose-gc";$api=Start-Process pnpm.cmd -ArgumentList @('exec','ts-node','src/main.ts') -WorkingDirectory (Join-Path $root 'apps/api') -RedirectStandardOutput (Join-Path $OutputRoot 'api.stdout.log') -RedirectStandardError (Join-Path $OutputRoot 'api.stderr.log') -WindowStyle Hidden -PassThru;$apiPid=0
try{for($i=0;$i-lt60;$i++){Start-Sleep -Milliseconds 500;$line=netstat -ano|Select-String ":$Port\s+.*LISTENING"|Select-Object -First 1;if($line){$apiPid=[int](($line.ToString()-split '\s+')[-1]);break}};if(-not$apiPid){throw'FAULT_ISOLATION_API_START_TIMEOUT'};&node scripts/fault-isolation-probe.mjs "http://127.0.0.1:$Port/api/v1" (Join-Path $OutputRoot 'fault-isolation.json');if($LASTEXITCODE-ne0){exit$LASTEXITCODE}}finally{if($apiPid){Stop-Process -Id $apiPid -Force -ErrorAction SilentlyContinue};if($api-and-not$api.HasExited){Stop-Process -Id $api.Id -Force -ErrorAction SilentlyContinue}}
Write-Output 'CONTROLLED FAULT ISOLATION - COMPLETE'
